SET NAMES utf8mb4;
SET time_zone = '+05:30';

CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, mobile VARCHAR(20), locality VARCHAR(120), status ENUM('pending','active','suspended') NOT NULL DEFAULT 'active', email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, INDEX(status), INDEX(locality)) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE issue_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT, is_active TINYINT(1) NOT NULL DEFAULT 1, position INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE civic_issues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT NOT NULL, locality VARCHAR(120) NOT NULL, ward VARCHAR(50), location_description VARCHAR(255), latitude DECIMAL(10,7), longitude DECIMAL(10,7), moderation_status ENUM('pending','approved','rejected','hidden') NOT NULL DEFAULT 'pending', progress_status ENUM('reported','under_review','action_initiated','escalated','resolved','closed') NOT NULL DEFAULT 'reported', is_featured TINYINT(1) NOT NULL DEFAULT 0, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES issue_categories(id), INDEX(moderation_status,progress_status), INDEX(locality), FULLTEXT(title,description)) ENGINE=InnoDB;
CREATE TABLE issue_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT UNSIGNED NOT NULL, media_id BIGINT UNSIGNED NULL, file_path VARCHAR(255) NOT NULL, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, file_size BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(issue_id) REFERENCES civic_issues(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE issue_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, previous_status VARCHAR(40), new_status VARCHAR(40) NOT NULL, public_update TEXT, internal_notes TEXT, evidence_path VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(issue_id) REFERENCES civic_issues(id) ON DELETE CASCADE, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(issue_id,created_at)) ENGINE=InnoDB;
CREATE TABLE issue_supports (issue_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(issue_id,user_id), FOREIGN KEY(issue_id) REFERENCES civic_issues(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE issue_followers (issue_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(issue_id,user_id), FOREIGN KEY(issue_id) REFERENCES civic_issues(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE issue_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, status ENUM('pending','approved','hidden') DEFAULT 'approved', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(issue_id) REFERENCES civic_issues(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(issue_id,status,created_at)) ENGINE=InnoDB;
CREATE TABLE discussion_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, is_active TINYINT(1) DEFAULT 1, position INT DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE discussions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, body TEXT NOT NULL, status ENUM('draft','pending','published','hidden','locked') DEFAULT 'pending', is_pinned TINYINT(1) DEFAULT 0, published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES discussion_categories(id), FULLTEXT(title,body), INDEX(status,published_at)) ENGINE=InnoDB;
CREATE TABLE discussion_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, discussion_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, body TEXT NOT NULL, status ENUM('pending','approved','hidden') DEFAULT 'approved', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(discussion_id) REFERENCES discussions(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(parent_id) REFERENCES discussion_comments(id), INDEX(discussion_id,status,created_at)) ENGINE=InnoDB;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT NOT NULL, featured_image VARCHAR(255), starts_at DATETIME NOT NULL, ends_at DATETIME, venue VARCHAR(180), address VARCHAR(255), organiser VARCHAR(180), capacity INT UNSIGNED, registration_enabled TINYINT(1) DEFAULT 0, cancellation_enabled TINYINT(1) DEFAULT 1, status ENUM('draft','published','archived') DEFAULT 'draft', published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FULLTEXT(title,description), INDEX(status,starts_at)) ENGINE=InnoDB;
CREATE TABLE event_registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, status ENUM('registered','cancelled','attended') DEFAULT 'registered', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(event_id,user_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE article_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED, author_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, summary TEXT, body MEDIUMTEXT NOT NULL, featured_image VARCHAR(255), status ENUM('draft','published','archived') DEFAULT 'draft', seo_title VARCHAR(180), meta_description VARCHAR(255), published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES article_categories(id), FOREIGN KEY(author_id) REFERENCES users(id), FULLTEXT(title,summary,body), INDEX(status,published_at)) ENGINE=InnoDB;
CREATE TABLE hero_banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, eyebrow VARCHAR(120), heading VARCHAR(180) NOT NULL, accent_text VARCHAR(180), description TEXT, desktop_image VARCHAR(255), mobile_image VARCHAR(255), cta_label VARCHAR(80), cta_url VARCHAR(255), secondary_cta_label VARCHAR(80), secondary_cta_url VARCHAR(255), layout ENUM('typography','image') DEFAULT 'typography', position INT DEFAULT 0, status ENUM('draft','published','archived') DEFAULT 'draft', starts_at DATETIME NULL, ends_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status,position)) ENGINE=InnoDB;
CREATE TABLE scrolling_strips (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, position INT DEFAULT 0, direction ENUM('up','down') DEFAULT 'down', speed_seconds DECIMAL(5,2) DEFAULT 17.00, is_visible TINYINT(1) DEFAULT 1, mobile_enabled TINYINT(1) DEFAULT 1, source_mode ENUM('manual','automatic') DEFAULT 'manual', source_type VARCHAR(40), source_limit INT DEFAULT 8, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE scrolling_strip_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, strip_id BIGINT UNSIGNED NOT NULL, title VARCHAR(120) NOT NULL, subtitle VARCHAR(120), content_type VARCHAR(40) NOT NULL, content_id BIGINT UNSIGNED NULL, destination_url VARCHAR(255), image_path VARCHAR(255), colour ENUM('coral','yellow','blue','dark','cream') DEFAULT 'coral', position INT DEFAULT 0, status ENUM('draft','published','archived') DEFAULT 'published', starts_at DATETIME NULL, ends_at DATETIME NULL, FOREIGN KEY(strip_id) REFERENCES scrolling_strips(id) ON DELETE CASCADE, INDEX(strip_id,status,position)) ENGINE=InnoDB;
CREATE TABLE announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, message VARCHAR(255) NOT NULL, link_url VARCHAR(255), priority ENUM('normal','urgent') DEFAULT 'normal', position INT DEFAULT 0, is_active TINYINT(1) DEFAULT 1, starts_at DATETIME NULL, ends_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(is_active,position)) ENGINE=InnoDB;
CREATE TABLE contact_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, subject VARCHAR(180) NOT NULL, message TEXT NOT NULL, status ENUM('new','in_progress','closed') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE volunteer_applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, mobile VARCHAR(20), locality VARCHAR(120), interests TEXT, status ENUM('pending','approved','declined') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, type VARCHAR(80) NOT NULL, title VARCHAR(180) NOT NULL, message TEXT NOT NULL, url VARCHAR(255), read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(user_id,read_at,created_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80), entity_id BIGINT UNSIGNED, metadata JSON NULL, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(entity_type,entity_id), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE rate_limit_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, action_key VARCHAR(80) NOT NULL, identity_hash CHAR(64) NOT NULL, attempts INT UNSIGNED DEFAULT 1, window_started_at DATETIME NOT NULL, blocked_until DATETIME NULL, UNIQUE(action_key,identity_hash), INDEX(blocked_until)) ENGINE=InnoDB;
CREATE TABLE password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE site_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;

